//go:build darwin

package verify

import "testing"

// procargs2 builds kern.procargs2 data: argc, the executable path with padding, the arguments
// and the environment, each NUL terminated.
func procargs2Fixture(argc byte, path string, args, env []string) []byte {
	data := append([]byte{argc, 0, 0, 0}, path+"\x00\x00\x00\x00"...)
	for _, s := range args {
		data = append(data, s+"\x00"...)
	}
	for _, s := range env {
		data = append(data, s+"\x00"...)
	}
	return data
}

func TestProcargs2MarkedExactEntry(t *testing.T) {
	t.Parallel()
	const mark = "KOGEN_MARK=run-1"
	cases := []struct {
		name string
		data []byte
		want bool
	}{
		{"environment entry", procargs2Fixture(2, "/bin/sleep", []string{"sleep", "60"}, []string{"PATH=/usr/bin", mark, "HOME=/h"}), true},
		{"only an argument", procargs2Fixture(3, "/bin/sh", []string{"sh", "-c", mark}, []string{"PATH=/usr/bin", "HOME=/h"}), false},
		{"longer value", procargs2Fixture(1, "/bin/sleep", []string{"sleep"}, []string{"PATH=/usr/bin", mark + "2"}), false},
		{"longer name", procargs2Fixture(1, "/bin/sleep", []string{"sleep"}, []string{"PATH=/usr/bin", "X_" + mark}), false},
	}
	for _, c := range cases {
		if got := procargs2Marked(c.data, mark); got != c.want {
			t.Errorf("%s: procargs2Marked = %v, want %v", c.name, got, c.want)
		}
	}
}

func TestProcargs2MarkedMalformed(t *testing.T) {
	t.Parallel()
	const mark = "KOGEN_MARK=run-1"
	cases := map[string][]byte{
		"empty":                      nil,
		"two bytes":                  {2, 0},
		"argument count only":        {1, 0, 0, 0},
		"unterminated path":          append([]byte{1, 0, 0, 0}, "/bin/sleep"+mark...),
		"unterminated argument":      append([]byte{2, 0, 0, 0}, "/bin/sh\x00\x00\x00\x00sh\x00"+mark...),
		"argc exceeds the arguments": procargs2Fixture(5, "/bin/sh", []string{"sh"}, []string{"PATH=/usr/bin", mark}),
	}
	for name, data := range cases {
		func() {
			defer func() {
				if r := recover(); r != nil {
					t.Errorf("%s: procargs2Marked panicked: %v", name, r)
				}
			}()
			if procargs2Marked(data, mark) {
				t.Errorf("%s: procargs2Marked matched malformed data", name)
			}
		}()
	}
}

